"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["91968"],{41232(e){e.exports=JSON.parse('{"id":"FIN-816","slug":"fixed-rate-mortgage","term":"Fixed-Rate Mortgage","also_known_as":[],"difficulty":"Beginner","definition":"A fixed-rate mortgage is a home loan with an interest rate that stays the same for an agreed period, or for the entire life of the loan, so the regular payments do not change during that time.","explanation":["With a fixed-rate mortgage, the borrower knows exactly what their payments will be, regardless of changes in market interest rates. This makes budgeting easier and protects against rising rates.","For example, a 200,000 mortgage at a fixed rate of 5%, repaid over 25 years, has monthly payments of about 1,169. Even if interest rates rise to 7%, the payment stays the same during the fixed period.","The length of the fixed period varies by country. In the United States, mortgages are commonly fixed for the full term, often 30 years. In the United Kingdom, rates are usually fixed for shorter periods, such as two or five years, after which the loan typically moves to a variable rate unless the borrower arranges a new deal. Other countries have their own patterns.","The trade-off is that fixed rates are sometimes higher than variable rates at the start, and borrowers do not benefit if market rates fall. Leaving a fixed-rate deal early may involve paying an early repayment charge."],"note":"","total":1500,"prev":{"slug":"fixed-rate","term":"Fixed Rate"},"next":{"slug":"flexible-budget","term":"Flexible Budget"}}')}}]);